    final owner=cloud.userId,version=cloud.sessionVersion;
    bool current()=>mounted&&cloud.userId==owner&&cloud.sessionVersion==version;
    try {
      final config=await cloud.request('/api/config');
      if(!current())return;
      final requiresSubscription=BillingService.requiredBuild||(config['subscription'] is Map&&config['subscription']['enabled']==true);
      var remote=await cloud.request('/api/catalog');
      if(!current())return;
      if(requiresSubscription&&cloud.signedIn){try{remote=await cloud.request('/api/member-catalog');}catch(_){/* Public metadata only when access cannot be verified. */}}
      if(current()&&remote['languages'] is List&&remote['lessons'] is List){subscriptionRequired=requiresSubscription;await s.cacheCatalog(remote);}
    }catch(_){/* Paid builds still require verified access at lesson entry. */}
  }
