    bool current()=>mounted&&cloud.userId==owner&&cloud.sessionVersion==version&&identical(s.learner,learner);
    if(subscriptionRequired){
      if(!cloud.signedIn){await login();return;}
      try{final status=await cloud.request('/api/entitlements');if(!current())return;if(status['subscriptionRequired']!=true)throw Exception('Subscription service is not activated.');if(status['access']!=true){await membership();return;}}catch(e){if(current())message(e.toString());return;}
    }
    if(!mounted||!current())return;
    await Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => LessonScreen(store: s,lesson: lesson,voice: voice)));
    if(current()&&cloud.signedIn){try{await cloud.sync(s);}catch(_){if(current())message(s.t('Saved on device. Use Sync now when connected.','آلے پر محفوظ۔ انٹرنیٹ آنے پر سنک کریں۔'));}}
    if(mounted)setState(() {});
  }
