class LessonScreen extends StatefulWidget {
  const LessonScreen({super.key,required this.store,required this.lesson,required this.voice});
  final LearningStore store;final Map<String,dynamic> lesson;final VoiceService voice;
  @override State<LessonScreen> createState()=>_LessonScreenState();
}
class _LessonScreenState extends State<LessonScreen> with WidgetsBindingObserver {
  int index=0,seconds=0;bool wrong=false,active=true,finished=false;
  Timer? timer,writingDelay;
  final writing=TextEditingController();
  late List<String?> answers;
  LearningStore get s=>widget.store;
  Map<String,dynamic> get l=>widget.lesson;
