    super.initState();WidgetsBinding.instance.addObserver(this);
    final saved=s.learner.sessions[l['id']] as Map?;
    index=((saved?['index'] as num?)?.toInt()??0).clamp(0,4).toInt();seconds=(saved?['seconds'] as num?)?.toInt()??0;
    final cached=saved?['answers'] is List?saved!['answers'] as List:[];
    answers=List.generate(questions.length,(i)=>i<cached.length&&cached[i] is String?cached[i] as String:null);
    writing.text=s.learner.drafts[l['id']] as String? ?? saved?['writing'] as String? ?? '';
    writing.addListener((){s.learner.drafts[l['id'] as String]=writing.text;persist(false);writingDelay?.cancel();writingDelay=Timer(const Duration(milliseconds:500),()=>s.save());});
    timer=Timer.periodic(const Duration(seconds:1),(_){if(!active||!mounted||finished)return;setState(()=>seconds++);persist(seconds%5==0);});
  }
  void persist([bool flush=true]){if(finished)return;s.learner.sessions[l['id'] as String]={'index':index,'seconds':seconds,'answers':answers,'writing':writing.text};if(flush)s.save();}
  @override void didChangeAppLifecycleState(AppLifecycleState state){active=state==AppLifecycleState.resumed;if(!active)persist();}
  @override void dispose(){timer?.cancel();writingDelay?.cancel();persist();WidgetsBinding.instance.removeObserver(this);writing.dispose();widget.voice.stop();super.dispose();}
  String clock()=>'${seconds~/60}:${(seconds%60).toString().padLeft(2,'0')}';
  Future<void> play(String text) async {try{await widget.voice.speak(text,s.learner.language);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}}
  Future<void> next() async {
    if(index<4){setState(()=>index++);persist();await widget.voice.stop();return;}
    if(answers.any((a)=>a==null)){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.t('Answer every question first.','پہلے ہر سوال کا جواب دیں۔'))));return;}
